async function importPicture(file){if(file.size>25*1024*1024)throw Error('Use pictures smaller than 25 MB.');if(!file.type.startsWith('image/'))throw Error('Choose an image file.');const url=URL.createObjectURL(file);try{const image=await loadImage(url),scale=Math.min(1,1400/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.86);}finally{URL.revokeObjectURL(url);}}
